using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<ModelTrainingService>();

var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");

// Train model at startup
var trainContext = new MLContext(seed: 42);
var trainData = trainContext.Data.LoadFromTextFile<TicketInput>(
    dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

var pipeline = trainContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject))
    .Append(trainContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
    .Append(trainContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
    .Append(trainContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category)))
    .Append(trainContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
    .Append(trainContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

var model = pipeline.Fit(trainData);
trainContext.Model.Save(model, trainData.Schema, modelPath);

builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapPost("/api/ticket/classify", (TicketRequest request, PredictionEnginePool<TicketInput, TicketPrediction> pool) =>
{
    if (string.IsNullOrWhiteSpace(request.Subject) && string.IsNullOrWhiteSpace(request.Description))
        return Results.BadRequest("Subject or Description is required.");

    if (request.Priority < 1 || request.Priority > 3)
        return Results.BadRequest("Priority must be between 1 and 3.");

    var input = new TicketInput
    {
        Subject = request.Subject,
        Description = request.Description,
        Priority = request.Priority
    };

    var prediction = pool.Predict(input);

    var categories = new[] { "Billing", "General", "Technical" };
    var scores = new Dictionary<string, float>();
    for (int i = 0; i < Math.Min(categories.Length, prediction.Score.Length); i++)
        scores[categories[i]] = prediction.Score[i];

    return Results.Ok(new TicketPredictionResponse
    {
        PredictedCategory = prediction.Category,
        Scores = scores
    });
});

app.MapPost("/api/ticket/train", (ModelTrainingService trainingService) =>
{
    var metrics = trainingService.TrainAndSaveModel(dataPath, modelPath);
    return Results.Ok(new { message = "Model trained successfully", metrics });
});

app.Run();

